def count_intersecting_pairs() -> int:
    N = int(input())
    intervals = []

    for _ in range(N):
        start, end = map(int, input().split())
        intervals.append((start, end))

    intersecting_pairs_count = 0

    for i in range(N):
        l_i, r_i = intervals[i]
        for j in range(i + 1, N):
            l_j, r_j = intervals[j]
            if l_i <= r_j and l_j <= r_i:
                intersecting_pairs_count += 1

    return intersecting_pairs_count
